SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-SXVI_NOTE_2B', type: 'note', label: '(b) Các bộ phận khác, nếu phù hợp để chỉ sử dụng...', code: '', section: 'XVI', chapter: '', description: '(b) Các bộ phận khác, nếu phù hợp để chỉ sử dụng hoặc chủ yếu sử dụng cho các loại máy cụ thể, hoặc cho một số loại máy cùng nhóm (kể cả máy thuộc nhóm 84.79 hoặc 85.43) được phân loại theo nhóm của các máy cụ thể đó hoặc vào nhóm thích hợp như 84.09, 84.31, 84.48, 84.66, 84.73, 85.03, 85.22, 85.29 ', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-SXVI_NOTE_2C', type: 'note', label: '(c) Tất cả các bộ phận khác được phân loại trong...', code: '', section: 'XVI', chapter: '', description: '(c) Tất cả các bộ phận khác được phân loại trong nhóm thích hợp như 84.09, 84.31, 84.48, 84.66, 84.73, 85.03, 85.22, 85.29 hoặc 85.38 hoặc, nếu không thì, phân loại vào nhóm 84.87 hoặc 85.48.', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-SXVI_NOTE_3', type: 'note', label: 'Trừ khi có yêu cầu cụ thể khác, các loại máy liê...', code: '', section: 'XVI', chapter: '', description: 'Trừ khi có yêu cầu cụ thể khác, các loại máy liên hợp gồm hai hoặc nhiều máy lắp ghép với nhau thành một thiết bị đồng bộ và các loại máy khác được thiết kế để thực hiện hai hoặc nhiều chức năng khác nhau hoặc bổ trợ lẫn nhau được phân loại theo bộ phận chính hoặc máy thực hiện chức năng chính.', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-SXVI_NOTE_4', type: 'note', label: 'Khi một máy (kể cả một tổ hợp máy) gồm các bộ ph...', code: '', section: 'XVI', chapter: '', description: 'Khi một máy (kể cả một tổ hợp máy) gồm các bộ phận cấu thành riêng lẻ (dù tách biệt hoặc được liên kết với nhau bằng ống, bằng bộ phận truyền, bằng cáp điện hoặc bằng bộ phận khác) để thực hiện một chức năng được xác định rõ đã quy định chi tiết tại một trong các nhóm của Chương 84 hoặc Chương 85, t', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-SXVI_NOTE_5', type: 'note', label: 'Theo mục đích của Chú giải này, khái niệm “máy” ...', code: '', section: 'XVI', chapter: '', description: 'Theo mục đích của Chú giải này, khái niệm “máy” có nghĩa là bất kỳ máy, máy móc, thiết bị, bộ dụng cụ hoặc dụng cụ đã nêu trong các nhóm của Chương 84 hoặc 85.', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-SXVI_NOTE_6A_INTRO', type: 'note', label: '(A) Trong toàn bộ Danh mục này, khái niệm “phế l...', code: '', section: 'XVI', chapter: '', description: '(A) Trong toàn bộ Danh mục này, khái niệm “phế liệu và phế thải điện và điện tử” có nghĩa là các cụm linh kiện điện và điện tử, tấm mạch in, và các sản phẩm điện hoặc điện tử:', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-SXVI_NOTE_6A_I', type: 'note', label: '(i) đã bị làm cho không sử dụng được cho các mục...', code: '', section: 'XVI', chapter: '', description: '(i) đã bị làm cho không sử dụng được cho các mục đích ban đầu của chúng do bị vỡ, cắt hoặc các quá trình khác hoặc không phù hợp về mặt kinh tế để sửa chữa, tân trang hoặc cải tạo để làm cho chúng phù hợp với mục đích ban đầu của chúng; và', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-SXVI_NOTE_6A_II', type: 'note', label: '(ii) được đóng gói hoặc vận chuyển theo cách khô...', code: '', section: 'XVI', chapter: '', description: '(ii) được đóng gói hoặc vận chuyển theo cách không nhằm mục đích bảo vệ các mặt hàng riêng lẻ khỏi bị hư hại trong quá trình vận chuyển, xếp và dỡ hàng hóa.', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-SXVI_NOTE_6B', type: 'note', label: '(B) Các lô hàng hỗn hợp gồm “phế liệu và phế thả...', code: '', section: 'XVI', chapter: '', description: '(B) Các lô hàng hỗn hợp gồm “phế liệu và phế thải điện và điện tử” và phế liệu và phế thải khác được phân loại vào nhóm 85.49.', has_children: true, children_count: 0}) $$) AS (v agtype);
