SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH84_NOTE_2_MAIN', type: 'note', label: 'Theo nội dung của Chú giải 3 Phần XVI và Chú giả...', code: '', section: 'XVI', chapter: '84', description: 'Theo nội dung của Chú giải 3 Phần XVI và Chú giải 11 của Chương này, máy móc hoặc thiết bị thỏa mãn mô tả của một hoặc nhiều nhóm từ 84.01 đến 84.24, hoặc nhóm 84.86 và đồng thời thỏa mãn mô tả của một hoặc nhiều nhóm từ 84.25 đến 84.80 thì được phân loại vào một nhóm thích hợp trong số các nhóm từ ', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH84_NOTE_2A', type: 'note', label: '(A) Tuy nhiên, nhóm 84.19 không bao gồm: (i) Máy...', code: '', section: 'XVI', chapter: '84', description: '(A) Tuy nhiên, nhóm 84.19 không bao gồm: (i) Máy ươm hạt giống, máy ấp trứng gia cầm và thiết bị sưởi ấm gia cầm mới nở (nhóm 84.36); (ii) Máy làm ẩm hạt (nhóm 84.37); (iii) Máy khuếch tán dùng để chiết xuất đường quả (nhóm 84.38); (iv) Máy để xử lý nhiệt đối với sợi dệt, vải hoặc các sản phẩm dệt (', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH84_NOTE_2B', type: 'note', label: '(B) Nhóm 84.22 không bao gồm: (i) Máy khâu dùng ...', code: '', section: 'XVI', chapter: '84', description: '(B) Nhóm 84.22 không bao gồm: (i) Máy khâu dùng để đóng túi hoặc các loại bao bì tương tự (nhóm 84.52); hoặc (ii) Máy văn phòng thuộc nhóm 84.72.', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH84_NOTE_2C', type: 'note', label: '(C) Nhóm 84.24 không bao gồm: (i) Máy in phun mự...', code: '', section: 'XVI', chapter: '84', description: '(C) Nhóm 84.24 không bao gồm: (i) Máy in phun mực (nhóm 84.43); hoặc (ii) Máy cắt bằng tia nước (nhóm 84.56).', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH84_NOTE_3', type: 'note', label: 'Máy công cụ để gia công loại vật liệu nào đó mà ...', code: '', section: 'XVI', chapter: '84', description: 'Máy công cụ để gia công loại vật liệu nào đó mà nó đáp ứng mô tả trong nhóm 84.56 và đồng thời đáp ứng mô tả trong nhóm 84.57, 84.58, 84.59, 84.60, 84.61, 84.64 hoặc 84.65 được phân loại trong nhóm 84.56.', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH84_NOTE_4', type: 'note', label: 'Nhóm 84.57 chỉ áp dụng cho máy công cụ để gia cô...', code: '', section: 'XVI', chapter: '84', description: 'Nhóm 84.57 chỉ áp dụng cho máy công cụ để gia công kim loại, trừ máy tiện (kể cả trung tâm gia công tiện), loại này có thể thực hiện được các kiểu thao tác gia công khác nhau: (a) bằng cách thay đổi công cụ công tác tự động từ hộp đựng hoặc tương tự theo đúng chương trình gia công (trung tâm gia côn', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH84_NOTE_5', type: 'note', label: 'Theo mục đích của nhóm 84.62, một \"dây chuyền xẻ...', code: '', section: 'XVI', chapter: '84', description: 'Theo mục đích của nhóm 84.62, một \"dây chuyền xẻ cuộn\" dùng cho các sản phẩm dạng phẳng là một dây chuyền xử lý gồm một máy xả cuộn, một máy làm phẳng cuộn, một máy xẻ và máy quấn cuộn. Một “dây chuyền cắt xén thành đoạn” dùng cho các sản phẩm dạng phẳng là một dây chuyền xử lý bao gồm một máy xả cu', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH84_NOTE_6A', type: 'note', label: '(A) Theo mục đích của nhóm 84.71, khái niệm \"máy...', code: '', section: 'XVI', chapter: '84', description: '(A) Theo mục đích của nhóm 84.71, khái niệm \"máy xử lý dữ liệu tự động\" là máy có khả năng: (i) Lưu trữ chương trình xử lý hoặc các chương trình và ít nhất lưu trữ các dữ liệu cần ngay cho việc thực hiện chương trình; (ii) Lập chương trình tùy theo yêu cầu của người sử dụng; (iii) Thực hiện các phép', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH84_NOTE_6B', type: 'note', label: '(B) Máy xử lý dữ liệu tự động có thể ở dạng hệ t...', code: '', section: 'XVI', chapter: '84', description: '(B) Máy xử lý dữ liệu tự động có thể ở dạng hệ thống bao gồm một số lượng biến thiên các khối chức năng riêng biệt.', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH84_NOTE_6C', type: 'note', label: '(C) Theo đoạn (D) và (E) dưới đây, khối chức năn...', code: '', section: 'XVI', chapter: '84', description: '(C) Theo đoạn (D) và (E) dưới đây, khối chức năng được xem như là bộ phận của một hệ thống xử lý dữ liệu tự động nếu thoả mãn tất cả các điều kiện sau: (i) Là loại chỉ sử dụng hoặc chủ yếu sử dụng trong hệ thống xử lý dữ liệu tự động; (ii) Có khả năng kết nối với bộ xử lý trung tâm hoặc trực tiếp ho', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH84_NOTE_6D', type: 'note', label: '(D) Nhóm 84.71 không bao gồm các hàng hóa sau đâ...', code: '', section: 'XVI', chapter: '84', description: '(D) Nhóm 84.71 không bao gồm các hàng hóa sau đây khi nó được trình bày riêng rẽ, ngay cả khi nó đáp ứng tất cả các điều kiện trong Chú giải 6 (C) nêu trên: (i) Máy in, máy photocopy, máy fax, có hoặc không liên hợp; (ii) Thiết bị truyền dẫn hoặc nhận âm thanh, hình ảnh hoặc dữ liệu khác, kể cả thiế', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH84_NOTE_6E', type: 'note', label: '(E) Các máy kết hợp hoặc làm việc kết hợp với mộ...', code: '', section: 'XVI', chapter: '84', description: '(E) Các máy kết hợp hoặc làm việc kết hợp với một máy xử lý dữ liệu tự động và thực hiện một chức năng riêng biệt không phải là chức năng xử lý dữ liệu được phân loại vào nhóm thích hợp với chức năng tương ứng của chúng hoặc, nếu không, sẽ được phân loại vào các nhóm còn lại.', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH84_NOTE_7', type: 'note', label: 'Không kể những đề cập khác, nhóm 84.82 áp dụng c...', code: '', section: 'XVI', chapter: '84', description: 'Không kể những đề cập khác, nhóm 84.82 áp dụng cho các bi thép đã đánh bóng, có dung sai lớn nhất và nhỏ nhất so với đường kính danh nghĩa không quá 1% hoặc không quá 0,05 mm, theo mức dung sai nhỏ hơn. Các loại bi thép khác được xếp vào nhóm 73.26.', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH84_NOTE_8', type: 'note', label: 'Theo yêu cầu của phân loại, máy móc sử dụng cho ...', code: '', section: 'XVI', chapter: '84', description: 'Theo yêu cầu của phân loại, máy móc sử dụng cho hai mục đích trở lên được phân loại theo mục đích sử dụng chính và mục đích này được coi như mục đích sử dụng duy nhất. Theo Chú giải 2 của Chương này và Chú giải 3 của Phần XVI, loại máy mà công dụng chính của nó không được mô tả trong bất kỳ nhóm nào', has_children: true, children_count: 0}) $$) AS (v agtype);
