SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH84_NOTE_10', type: 'note', label: 'Theo mục đích của nhóm 84.85, khái niệm “công ng...', code: '', section: 'XVI', chapter: '84', description: 'Theo mục đích của nhóm 84.85, khái niệm “công nghệ sản xuất bồi đắp” (còn được gọi là công nghệ in 3D) có nghĩa là sự hình thành các vật thể hữu hình, dựa trên mô hình kỹ thuật số, bằng cách đắp chồng và tạo lớp liên tiếp, và hợp nhất (consolidation) và đóng rắn (solidification), từ vật liệu (ví dụ,', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH84_NOTE_11A', type: 'note', label: '(A) Chú giải 9 (a) và 9 (b) Chương 85 cũng áp dụ...', code: '', section: 'XVI', chapter: '84', description: '(A) Chú giải 9 (a) và 9 (b) Chương 85 cũng áp dụng đối với khái niệm “thiết bị bán dẫn” và “mạch điện tử tích hợp”, như đã được sử dụng trong Chú giải này và trong nhóm 84.86. Tuy nhiên, theo mục đích của Chú giải này và của nhóm 84.86, khái niệm “thiết bị bán dẫn” cũng bao gồm các thiết bị bán dẫn ', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH84_NOTE_11B', type: 'note', label: '(B) Theo mục đích của Chú giải này và của nhóm 8...', code: '', section: 'XVI', chapter: '84', description: '(B) Theo mục đích của Chú giải này và của nhóm 84.86, khái niệm “sản xuất màn hình dẹt” bao gồm chế tạo các lớp nền (các lớp cơ bản cấu thành) của tấm dẹt màn hình. Nó không bao gồm công đoạn gia công, sản xuất kính hoặc lắp ráp các tấm mạch in hoặc các bộ phận điện tử khác vào tấm dẹt màn hình. Khá', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH84_NOTE_11C', type: 'note', label: '(C) Nhóm 84.86 cũng bao gồm những máy móc và thi...', code: '', section: 'XVI', chapter: '84', description: '(C) Nhóm 84.86 cũng bao gồm những máy móc và thiết bị chỉ sử dụng hoặc chủ yếu sử dụng để: (i) sản xuất hoặc sửa chữa màn (khuôn in) và lưới quang; (ii) lắp ghép thiết bị bán dẫn hoặc các mạch điện tử tích hợp; (iii) bộ phận nâng, giữ, xếp vào hoặc tháo dỡ khối bán dẫn, tấm bán dẫn mỏng, thiết bị bá', has_children: true, children_count: 0}) $$) AS (v agtype);
