SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH85_NOTE_6A', type: 'note', label: '(a) \"Các thiết bị lưu trữ bền vững, thể rắn (sản...', code: '', section: 'XVI', chapter: '85', description: '(a) \"Các thiết bị lưu trữ bền vững, thể rắn (sản phẩm lưu trữ bán dẫn không bị xoá dữ liệu khi không còn nguồn điện cung cấp)\" (ví dụ, “thẻ nhớ flash (flash memory cards)” hoặc “thẻ lưu trữ điện tử flash (flash electronic storage cards)”) là thiết bị lưu trữ gắn với đầu kết nối (đầu cắm nối), có chứ', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH85_NOTE_6B', type: 'note', label: '(b) Khái niệm “thẻ thông minh” nghĩa là thẻ được...', code: '', section: 'XVI', chapter: '85', description: '(b) Khái niệm “thẻ thông minh” nghĩa là thẻ được gắn bên trong một hoặc nhiều mạch điện tử tích hợp (bộ vi xử lý, bộ nhớ truy cập ngẫu nhiên (RAM) hoặc bộ nhớ chỉ đọc (ROM)) ở dạng các chip. Các thẻ này có thể bao gồm các tiếp điểm, dải từ tính hoặc ăng ten gắn bên trong nhưng không chứa bất cứ phần', has_children: true, children_count: 0}) $$) AS (v agtype);
