SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH85_NOTE_9', type: 'note', label: 'Theo mục đích của nhóm 85.36, “đầu nối dùng cho ...', code: '', section: 'XVI', chapter: '85', description: 'Theo mục đích của nhóm 85.36, “đầu nối dùng cho sợi quang, bó sợi quang hoặc cáp quang” nghĩa là đầu nối chỉ dùng để ghép nối đối đầu một cách cơ học các sợi quang trong hệ thống đường truyền kỹ thuật số. Chúng không có chức năng khác, như khuếch đại, tái tạo hoặc biến đổi tín hiệu.', has_children: true, children_count: 0}) $$) AS (v agtype);
