SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH85_NOTE_11B', type: 'note', label: '(b) “Đèn đi-ốt phát quang (LED)” là nguồn sáng đ...', code: '', section: 'XVI', chapter: '85', description: '(b) “Đèn đi-ốt phát quang (LED)” là nguồn sáng điện gồm một hoặc nhiều mô-đun LED có chứa thêm các phần tử như phần tử điện, cơ, nhiệt hoặc quang học. Sự khác biệt giữa mô-đun đi-ốt phát quang (LED) và bóng đèn đi-ốt phát quang (LED) là đèn (lamp) có đầu đèn được thiết kế để cho phép dễ dàng lắp đặt', has_children: true, children_count: 0}) $$) AS (v agtype);
