SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH85_NOTE_12A_I_TRANSDUCER', type: 'note', label: 'Theo mục đích của định nghĩa này, “Bộ chuyển đổi...', code: '', section: 'XVI', chapter: '85', description: 'Theo mục đích của định nghĩa này, “Bộ chuyển đổi dựa trên chất bán dẫn” là cảm biến dựa trên chất bán dẫn, bộ truyền động dựa trên chất bán dẫn, bộ cộng hưởng dựa trên chất bán dẫn và bộ tạo dao động dựa trên chất bán dẫn, là các loại thiết bị dựa trên chất bán dẫn riêng biệt, thực hiện một chức năn', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH85_NOTE_12A_I_DEF1', type: 'note', label: '(1) “Dựa trên chất bán dẫn” có nghĩa là được chế...', code: '', section: 'XVI', chapter: '85', description: '(1) “Dựa trên chất bán dẫn” có nghĩa là được chế tạo hoặc sản xuất trên nền bán dẫn hoặc làm bằng vật liệu bán dẫn, được sản xuất bằng công nghệ bán dẫn, trong đó chất nền hoặc vật liệu bán dẫn đóng vai trò quan trọng và không thể thay thế đối với chức năng và hiệu suất của bộ chuyển đổi và hoạt độn', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH85_NOTE_12A_I_DEF2', type: 'note', label: '(2) “Đại lượng vật lý hoặc đại lượng hóa học” li...', code: '', section: 'XVI', chapter: '85', description: '(2) “Đại lượng vật lý hoặc đại lượng hóa học” liên quan đến các đại lượng như áp suất, sóng âm thanh, gia tốc, rung, chuyển động, phương hướng, sức căng, cường độ từ trường, cường độ điện trường, ánh sáng, phóng xạ, độ ẩm, dòng chảy, nồng độ hóa chất...', has_children: false, children_count: 0}) $$) AS (v agtype);
