SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH85_NOTE_12_PRIORITY', type: 'note', label: 'Để phân loại những mặt hàng được định nghĩa tron...', code: '', section: 'XVI', chapter: '85', description: 'Để phân loại những mặt hàng được định nghĩa trong Chú giải này, các nhóm 85.41 và 85.42 được ưu tiên xem xét trước hết so với bất kỳ nhóm nào khác trong Danh mục hàng hóa, trừ các mặt hàng thuộc nhóm 85.23.', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH85_SUBNOTE_1', type: 'note', label: 'Phân nhóm 8525.81 chỉ bao gồm camera truyền hình...', code: '', section: 'XVI', chapter: '85', description: 'Phân nhóm 8525.81 chỉ bao gồm camera truyền hình, camera kỹ thuật số và camera ghi hình ảnh tốc độ cao có một hoặc nhiều đặc điểm sau: - tốc độ ghi trên 0,5 mm mỗi micro giây; - độ phân giải thời gian từ 50 nano giây trở xuống; - tốc độ khung hình trên 225.000 khung hình mỗi giây.', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH85_SUBNOTE_2', type: 'note', label: 'Đối với phân nhóm 8525.82, camera truyền hình, c...', code: '', section: 'XVI', chapter: '85', description: 'Đối với phân nhóm 8525.82, camera truyền hình, camera kỹ thuật số và camera ghi hình ảnh được làm cứng bức xạ hoặc chịu bức xạ được thiết kế hoặc được che chắn để có thể hoạt động trong môi trường bức xạ cao. Các camera này được thiết kế để chịu được tổng lượng bức xạ ít nhất là 50 X 10^3Gy(silic) (', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVI-N-CH85_SUBNOTE_3', type: 'note', label: 'Phân nhóm 8525.83 bao gồm camera truyền hình, ca...', code: '', section: 'XVI', chapter: '85', description: 'Phân nhóm 8525.83 bao gồm camera truyền hình, camera kỹ thuật số và camera ghi hình ảnh nhìn ban đêm sử dụng một ca-tốt quang điện (photocathode) để chuyển đổi ánh sáng có sẵn thành các điện tử (electrons), có thể được khuếch đại và chuyển đổi để mang lại hình ảnh nhìn thấy được. Phân nhóm này loại ', has_children: true, children_count: 0}) $$) AS (v agtype);
