SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:XIV_CH71_NOTE_01', type: 'note', label: '1. Theo Chú giải 1 (A) của Phần VI và loại trừ n...', code: '', section: 'XIV', chapter: '71', description: '1. Theo Chú giải 1 (A) của Phần VI và loại trừ những sản phẩm được liệt kê ở các mục dưới đây, thì tất cả các sản phẩm gồm toàn bộ hoặc từng phần bằng: (a) Ngọc trai tự nhiên hoặc nuôi cấy hoặc bằng đá quý hoặc đá bán quý (tự nhiên, tổng hợp hoặc tái tạo), hoặc (b) Kim loại quý hoặc kim loại dát phủ', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:XIV_CH71_NOTE_02', type: 'note', label: '2. (A) Nhóm 71.13, 71.14 và 71.15 không bao gồm ...', code: '', section: 'XIV', chapter: '71', description: '2. (A) Nhóm 71.13, 71.14 và 71.15 không bao gồm các sản phẩm mà trong đó kim loại quý hoặc kim loại được dát phủ kim loại quý chỉ đóng vai trò như là thành phần phụ, chẳng hạn như các đồ đính kèm hoặc đồ trang trí phụ (ví dụ, chữ lồng, đai và viền), và mục (b) của Chú giải trên không áp dụng cho các', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:XIV_CH71_NOTE_03', type: 'note', label: '3. Chương này không bao gồm: (a) Hỗn hống của ki...', code: '', section: 'XIV', chapter: '71', description: '3. Chương này không bao gồm: (a) Hỗn hống của kim loại quý, hoặc kim loại quý dạng keo (nhóm 28.43); (b) Vật liệu khâu vô trùng trong phẫu thuật, các chất hàn răng hoặc các hàng hoá khác thuộc Chương 30; (c) Các sản phẩm thuộc Chương 32 (ví dụ, các chất bóng); (d) Các chất xúc tác có nền (nhóm 38.15', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:XIV_CH71_NOTE_04', type: 'note', label: '4. (A) Khái niệm \"kim loại quý\" nghĩa là bạc, và...', code: '', section: 'XIV', chapter: '71', description: '4. (A) Khái niệm \"kim loại quý\" nghĩa là bạc, vàng và bạch kim. (B) Khái niệm \"bạch kim\" nghĩa là platin, iridi, osmi, palladi, rodi và rutheni. (C) Khái niệm \"đá quý hoặc đá bán quý\" không bao gồm bất cứ một loại nào đã được ghi trong Chú giải 2(b) của Chương 96.', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:XIV_CH71_NOTE_05', type: 'note', label: '5. Theo mục đích của Chương này, hợp kim bất kỳ ...', code: '', section: 'XIV', chapter: '71', description: '5. Theo mục đích của Chương này, hợp kim bất kỳ (kể cả hỗn hợp thiêu kết và hợp chất liên kết kim loại) có chứa kim loại quý được xem như là một hợp kim của kim loại quý nếu kim loại quý đó cấu thành bằng 2% tính theo khối lượng của hợp kim. Các hợp kim của kim loại quý được phân loại theo các quy t', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:XIV_CH71_NOTE_06', type: 'note', label: '6. Trong Danh mục này, trừ khi có yêu cầu khác, ...', code: '', section: 'XIV', chapter: '71', description: '6. Trong Danh mục này, trừ khi có yêu cầu khác, khi đề cập đến kim loại quý hoặc bất kỳ một kim loại quý cụ thể cần đề cập đến cả các hợp kim đã được coi như hợp kim của kim loại quý hoặc của kim loại quý cụ thể đó theo quy định đã nêu trong Chú giải 5 trên đây, nhưng không áp dụng với kim loại được', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:XIV_CH71_NOTE_07', type: 'note', label: '7. Trong toàn bộ Danh mục này khái niệm \"kim loạ...', code: '', section: 'XIV', chapter: '71', description: '7. Trong toàn bộ Danh mục này khái niệm \"kim loại được dát phủ kim loại quý\" có nghĩa là vật liệu có nền là kim loại mà trên một mặt hoặc nhiều mặt của kim loại đó được phủ kim loại quý bằng cách hàn thiếc, hàn hơi, hàn điện, cán nóng hoặc các phương pháp bọc phủ cơ khí tương tự. Trừ khi có yêu cầu ', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:XIV_CH71_NOTE_08', type: 'note', label: '8. Theo Chú giải 1(A) Phần VI, các hàng hoá giốn...', code: '', section: 'XIV', chapter: '71', description: '8. Theo Chú giải 1(A) Phần VI, các hàng hoá giống như mô tả của nhóm 71.12 được phân loại vào nhóm đó và không được xếp vào nhóm nào khác của Danh mục.', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:XIV_CH71_NOTE_09', type: 'note', label: '9. Theo mục đích của nhóm 71.13, khái niệm \"đồ t...', code: '', section: 'XIV', chapter: '71', description: '9. Theo mục đích của nhóm 71.13, khái niệm \"đồ trang sức\" có nghĩa là: (a) Các đồ vật nhỏ để trang sức cá nhân (ví dụ, nhẫn, vòng đeo tay, dây chuyền, trâm cài, hoa tai, dây đồng hồ, dây đeo đồng hồ bỏ túi, mặt dây chuyền, ghim cài cà vạt, khuy cài cổ tay áo, khuy cúc khác, huy chương và phù hiệu tô', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:XIV_CH71_NOTE_10', type: 'note', label: '10. Theo mục đích của nhóm 71.14, khái niệm \"đồ ...', code: '', section: 'XIV', chapter: '71', description: '10. Theo mục đích của nhóm 71.14, khái niệm \"đồ kỹ nghệ vàng hoặc bạc\" kể cả các sản phẩm như các đồ vật trang trí, bộ đồ ăn, đồ vệ sinh, đồ dùng của người hút thuốc và các sản phẩm khác sử dụng trong gia đình, văn phòng hoặc tôn giáo.', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:XIV_CH71_NOTE_11', type: 'note', label: '11. Theo mục đích của nhóm 71.17, khái niệm \"đồ ...', code: '', section: 'XIV', chapter: '71', description: '11. Theo mục đích của nhóm 71.17, khái niệm \"đồ trang sức làm bằng chất liệu khác\" có nghĩa là các sản phẩm trang sức như đã mô tả trong nội dung của mục (a) Chú giải 9 ở trên (nhưng không kể các loại khuy cài hoặc các sản phẩm khác thuộc nhóm 96.06, hoặc lược chải, trâm cài tóc hoặc các loại tương ', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:XIV_CH71_SUBHEADING_NOTE_01', type: 'note', label: '1. Theo mục đích của các phân nhóm 7106.10, 7108...', code: '', section: 'XIV', chapter: '71', description: '1. Theo mục đích của các phân nhóm 7106.10, 7108.11, 7110.11, 7110.21, 7110.31 và 7110.41, khái niệm \"bột\" và \"dạng bột\" có nghĩa là các sản phẩm có 90% trở lên tính theo khối lượng lọt qua rây (sàng) có đường kính mắt rây (sàng) 0,5 mm.', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:XIV_CH71_SUBHEADING_NOTE_02', type: 'note', label: '2. Mặc dù đã quy định trong Chú giải 4 (B) của C...', code: '', section: 'XIV', chapter: '71', description: '2. Mặc dù đã quy định trong Chú giải 4 (B) của Chương này, nhưng theo các phân nhóm 7110.11 và 7110.19, khái niệm \"bạch kim\" không bao gồm iridi, osmi, paladi, rodi hoặc rutheni.', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:XIV_CH71_SUBHEADING_NOTE_03', type: 'note', label: '3. Theo phân loại các hợp kim trong các phân nhó...', code: '', section: 'XIV', chapter: '71', description: '3. Theo phân loại các hợp kim trong các phân nhóm của nhóm 71.10, mỗi hợp kim được phân loại theo kim loại, bạch kim, paladi, rodi, iridi, osmi hoặc rutheni có hàm lượng trội hơn so với mỗi kim loại khác.', has_children: false, children_count: 0}) $$) AS (v agtype);
