SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:DEF_001', type: 'note', label: 'Theo mục đích của Chương này, \"xe kéo\" có nghĩa ...', code: '', section: 'XVII', chapter: '87', description: 'Theo mục đích của Chương này, \"xe kéo\" có nghĩa là phương tiện được thiết kế chủ yếu để kéo hoặc đẩy một phương tiện, một thiết bị hoặc một vật nặng khác, có hoặc không bao gồm bộ phận phụ trợ để vận chuyển các loại công cụ, hạt giống (seeds), phân bón hoặc hàng hoá khác, phù hợp với mục đích sử dụn', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:DEF_002', type: 'note', label: '1. Theo mục đích của Chương này, khái niệm “phươ...', code: '', section: 'XVII', chapter: '88', description: '1. Theo mục đích của Chương này, khái niệm “phương tiện bay không người lái” có nghĩa là bất kỳ phương tiện bay nào, trừ các phương tiện bay thuộc nhóm 88.01, được thiết kế để bay mà không có người lái trên phương tiện bay. Chúng có thể được thiết kế để mang trọng tải hoặc được trang bị camera kỹ th', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:DEF_003', type: 'note', label: '1. Theo mục đích của các phân nhóm từ 8802.11 đế...', code: '', section: 'XVII', chapter: '88', description: '1. Theo mục đích của các phân nhóm từ 8802.11 đến 8802.40, khái niệm \"trọng lượng không tải\" nghĩa là trọng lượng của máy móc ở chế độ bay bình thường, không bao gồm trọng lượng của tổ bay và trọng lượng của nhiên liệu và thiết bị trừ các thiết bị được gắn cố định.', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:DEF_004', type: 'note', label: 'Theo mục đích của các phân nhóm 8806.21 đến 8806...', code: '', section: 'XVII', chapter: '88', description: 'Theo mục đích của các phân nhóm 8806.21 đến 8806.24 và 8806.91 đến 8806.94, khái niệm \"trọng lượng cất cánh tối đa\" có nghĩa là trọng lượng tối đa của phương tiện bay ở chê độ bay bình thường, khi cất cánh, kể cả trọng lượng của trọng tải, thiết bị và nhiên liệu.', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:Chapter {id: 'tt31:SXVII_CH_86', type: 'chapter', label: 'Chương 86: Đầu máy, các phương tiện di chuyển trên đường sắ...', code: '86', section: 'XVII', chapter: '86', description: 'Đầu máy, các phương tiện di chuyển trên đường sắt hoặc đường tàu điện và các bộ phận của chúng; các bộ phận cố định và ghép nối đường ray đường sắt hoặc tàu điện và bộ phận của chúng; thiết bị tín hiệu giao thông bằng cơ khí (kể cả cơ điện) các loại', has_children: true, children_count: 9}) $$) AS (v agtype);
