SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:CH86_NOTE_2', type: 'note', label: 'Nhóm 86.07, không kể những đề cập khác, áp dụng ...', code: '', section: 'XVII', chapter: '86', description: 'Nhóm 86.07, không kể những đề cập khác, áp dụng cho: Trục, bánh xe, bộ trục bánh xe (1) (bánh răng truyền động), đai bánh xe (1), mâm bánh và moay ơ và các bộ phận khác của bánh xe; Khung, bệ xe (1), giá chuyển hướng và trục bitxen; Hộp trục (1); cơ câu hãm (1); Bộ giảm chân đầu đâm cho các phương t', has_children: false, children_count: 0}) $$) AS (v agtype);
