SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:CH87_NOTE_1', type: 'note', label: 'Chương này không bao gồm phương tiện chạy trên đ...', code: '', section: 'XVII', chapter: '87', description: 'Chương này không bao gồm phương tiện chạy trên đường sắt hoặc đường tàu điện được thiết kế chỉ để chạy trên đường ray.', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:CH87_NOTE_2', type: 'note', label: 'Theo mục đích của Chương này, \"xe kéo\" có nghĩa ...', code: '', section: 'XVII', chapter: '87', description: 'Theo mục đích của Chương này, \"xe kéo\" có nghĩa là phương tiện được thiết kế chủ yếu để kéo hoặc đẩy một phương tiện, một thiết bị hoặc một vật nặng khác, có hoặc không bao gồm bộ phận phụ trợ để vận chuyển các loại công cụ, hạt giống (seeds), phân bón hoặc hàng hoá khác, phù hợp với mục đích sử dụn', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:CH87_NOTE_3', type: 'note', label: 'Khung gầm có động cơ gắn với cabin xếp ở các nhó...', code: '', section: 'XVII', chapter: '87', description: 'Khung gầm có động cơ gắn với cabin xếp ở các nhóm từ 87.02 đến 87.04, và không thuộc nhóm 87.06.', has_children: false, children_count: 0}) $$) AS (v agtype);
