SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:CH87_SUBNOTE_1', type: 'note', label: '1. Phân nhóm 8708.22 bao gồm: (a) kính chắn gió ...', code: '', section: 'XVII', chapter: '87', description: '1. Phân nhóm 8708.22 bao gồm: (a) kính chắn gió phía trước (kính chắn gió), kính cửa phía sau và các kính cửa khác, có khung; và (b) kính chắn gió phía trước (kính chắn gió), kính cửa phía sau và các kính cửa khác, có hoặc không có khung, có gắn thiết bị sưởi hoặc các thiết bị điện hoặc điện tử khác', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:CH88_NOTE_1', type: 'note', label: '1. Theo mục đích của Chương này, khái niệm “phươ...', code: '', section: 'XVII', chapter: '88', description: '1. Theo mục đích của Chương này, khái niệm “phương tiện bay không người lái” có nghĩa là bất kỳ phương tiện bay nào, trừ các phương tiện bay thuộc nhóm 88.01, được thiết kế để bay mà không có người lái trên phương tiện bay. Chúng có thể được thiết kế để mang trọng tải hoặc được trang bị camera kỹ th', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:CH88_SUBNOTE_1', type: 'note', label: '1. Theo mục đích của các phân nhóm từ 8802.11 đế...', code: '', section: 'XVII', chapter: '88', description: '1. Theo mục đích của các phân nhóm từ 8802.11 đến 8802.40, khái niệm \"trọng lượng không tải\" nghĩa là trọng lượng của máy móc ở chế độ bay bình thường, không bao gồm trọng lượng của tổ bay và trọng lượng của nhiên liệu và thiết bị trừ các thiết bị được gắn cố định.', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:CH88_SUBNOTE_2', type: 'note', label: 'Theo mục đích của các phân nhóm 8806.21 đến 8806...', code: '', section: 'XVII', chapter: '88', description: 'Theo mục đích của các phân nhóm 8806.21 đến 8806.24 và 8806.91 đến 8806.94, khái niệm \"trọng lượng cất cánh tối đa\" có nghĩa là trọng lượng tối đa của phương tiện bay ở chê độ bay bình thường, khi cất cánh, kể cả trọng lượng của trọng tải, thiết bị và nhiên liệu.', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:CH89_NOTE_1', type: 'note', label: '1. Thân tàu, tàu chưa hoàn chỉnh hoặc chưa hoàn ...', code: '', section: 'XVII', chapter: '89', description: '1. Thân tàu, tàu chưa hoàn chỉnh hoặc chưa hoàn thiện, đã lắp ráp, hoặc chưa lắp ráp hoặc tháo rời, hoặc tàu hoàn chỉnh chưa lắp ráp hoặc tháo rời, được phân loại vào nhóm 89.06 nêu không có đặc trưng cơ bản của một loại tàu cụ thể.', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVII_NOTE_1', type: 'note', label: 'Phần này không bao gồm các mặt hàng thuộc các nh...', code: '', section: 'XVII', chapter: '', description: 'Phần này không bao gồm các mặt hàng thuộc các nhóm 95.03 hoặc 95.08, hoặc xe trượt băng, xe trượt tuyết hoặc loại tương tự thuộc nhóm 95.06.', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVII_NOTE_2', type: 'note', label: 'Khái niệm \"bộ phận\" và \"bộ phận và phụ kiện\" khô...', code: '', section: 'XVII', chapter: '', description: 'Khái niệm \"bộ phận\" và \"bộ phận và phụ kiện\" không áp dụng cho các sản phẩm sau đây, dù chúng có hoặc không được nhận biết như những bộ phận dùng cho hàng hoá thuộc Phần này: Tấm đệm, vòng đệm hoặc loại tương tự bằng vật liệu bất kỳ (được phân loại theo vật liệu cấu thành hoặc được xếp vào nhóm 84.8', has_children: true, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVII_NOTE_3', type: 'note', label: 'Khi đề cập đến các Chương từ Chương 86 đến Chươn...', code: '', section: 'XVII', chapter: '', description: 'Khi đề cập đến các Chương từ Chương 86 đến Chương 88 khái niệm “bộ phận” hoặc \"phụ kiện\" không áp dụng cho loại bộ phận hoặc phụ kiện không phù hợp để chỉ dùng hoặc chủ yếu dùng với các mặt hàng thuộc các Chương này. Một loại bộ phận hoặc phụ kiện đáp ứng mô tả trong hai hoặc nhiều nhóm thuộc các Ch', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVII_NOTE_4', type: 'note', label: 'Theo mục đích của Phần này: Các phương tiện được...', code: '', section: 'XVII', chapter: '', description: 'Theo mục đích của Phần này: Các phương tiện được thiết kế đặc biệt để chạy cả trên đường bộ và đường ray được phân loại vào nhóm thích hợp của Chương 87; Xe lội nước có động cơ được phân loại vào nhóm thích hợp của Chương 87; Phương tiện bay được thiết kế đặc biệt để cũng có thể sử dụng như loại phư', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt31:SXVII_NOTE_5', type: 'note', label: 'Các phương tiện chạy trên đệm không khí được phâ...', code: '', section: 'XVII', chapter: '', description: 'Các phương tiện chạy trên đệm không khí được phân loại trong Phần này cùng với các phương tiện giống chúng nhất cụ thể như sau: xếp vào Chương 86 nếu chúng được thiết kế để chạy trên đường ray dẫn (tàu hoả chạy trên đệm không khí); xếp vào Chương 87 nếu chúng được thiết kế để chạy trên đất hoặc trên', has_children: false, children_count: 0}) $$) AS (v agtype);
