SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'nd26_cp:p187', type: 'note', label: 'Trường hợp hồ sơ chưa đầy đủ theo quy định, cơ q...', code: '', section: '', chapter: '', description: 'Trường hợp hồ sơ chưa đầy đủ theo quy định, cơ quan hải quan có văn bản đề nghị doanh nghiệp bổ sung hồ sơ. Trường hợp nghi vấn về tính chính xác của hồ sơ, cơ quan hải quan thực hiện kiểm tra tại trụ sở cơ quan hải quan hoặc trụ sở của người nộp thuế theo quy định của pháp luật về quản lý thuế.', has_children: false, children_count: 0}) $$) AS (v agtype);
