SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'nd26_cp:p214', type: 'note', label: '4. Thuế suất thuế nhập khẩu ưu đãi đối với linh ...', code: '', section: '', chapter: '', description: '4. Thuế suất thuế nhập khẩu ưu đãi đối với linh kiện ô tô nhập khẩu thuộc nhóm 98.49 quy định tại Điều 8 Nghị định này được áp dụng đến ngày 31 tháng 12 năm 2027. Các doanh nghiệp đã đăng ký tham gia Chương trình ưu đãi thuế trước ngày Nghị định này có hiệu lực thi hành phải thực hiện đăng ký lại vớ', has_children: false, children_count: 0}) $$) AS (v agtype);
