SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt02_btttt:p83', type: 'note', label: '(4) Thiết bị vô tuyến điện cự ly ngắn tại mục nà...', code: '', section: '', chapter: '', description: '(4) Thiết bị vô tuyến điện cự ly ngắn tại mục này không bao gồm thiết bị chỉ thu vô tuyến; thiết bị truyền dữ liệu băng rộng hoạt động trong băng tần 2,4 GHz có công suất bức xạ đẳng hướng tương đương (EIRP) nhỏ hơn 60 mW; thiết bị truy nhập vô tuyến băng tần 5 GHz có công suất bức xạ đẳng hướng tươ', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt02_btttt:p84', type: 'note', label: 'Thiết bị truyền dữ liệu băng rộng, thiết bị truy...', code: '', section: '', chapter: '', description: 'Thiết bị truyền dữ liệu băng rộng, thiết bị truy nhập vô tuyến độc lập hoạt động trên một hoặc nhiều băng tần có hỗ trợ băng tần 6 GHz (5,925 GHz đến 7,125 GHz) (sau đây gọi là thiết bị Wi-Fi 6E, Wi-Fi 7) chỉ được thực hiện công bố hợp quy với điều kiện nhà sản xuất thiết bị Wi-Fi 6E, Wi-Fi 7 có văn', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt02_btttt:p85', type: 'note', label: 'Thiết bị có tích hợp chức năng của thiết bị Wi-F...', code: '', section: '', chapter: '', description: 'Thiết bị có tích hợp chức năng của thiết bị Wi-Fi 6E, Wi-Fi 7 chỉ được thực hiện công bố hợp quy với điều kiện nhà sản xuất thiết bị có tích hợp chức năng của thiết bị Wi-Fi 6E, Wi-Fi 7 có văn bản cam kết đã tắt băng tần 6 GHz và người sử dụng không thể kích hoạt, sử dụng băng tần này nếu không có s', has_children: false, children_count: 0}) $$) AS (v agtype);
SELECT * FROM cypher('customs_tariff_graph', $$ CREATE (:LegalNote {id: 'tt02_btttt:p86', type: 'note', label: '(5) Chỉ thực hiện công bố hợp quy khi thiết bị p...', code: '', section: '', chapter: '', description: '(5) Chỉ thực hiện công bố hợp quy khi thiết bị phù hợp về băng tần và điều kiện kỹ thuật, khai thác theo quy định tại Thông tư số 08/2021/TT-BTTTT ngày 14 tháng 10 năm 2021 của Bộ trưởng Bộ Thông tin và Truyền thông quy định Danh mục thiết bị vô tuyến điện được miễn giấy phép sử dụng tần số vô tuyến', has_children: false, children_count: 0}) $$) AS (v agtype);
